import{ax as a,A as i,aQ as e,z as l}from"./chunks/framework.BWRXlwpK.js";const k=JSON.parse('{"title":"服务器资源","description":"","frontmatter":{},"headers":[],"relativePath":"linux/useLinux/use-server.md","filePath":"linux/useLinux/use-server.md","lastUpdated":1788148933000}'),t={name:"linux/useLinux/use-server.md"};function n(p,s,h,d,o,c){return l(),i("div",null,s[0]||(s[0]=[e(`<h1 id="服务器资源" tabindex="-1">服务器资源 <a class="header-anchor" href="#服务器资源" aria-label="Permalink to &quot;服务器资源&quot;">​</a></h1><h2 id="df-查看磁盘" tabindex="-1">df（查看磁盘） <a class="header-anchor" href="#df-查看磁盘" aria-label="Permalink to &quot;df（查看磁盘）&quot;">​</a></h2><p>java项目运行一段时间后，日志会越来越多</p><p>例如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">logs/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    app.log</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    error.log</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    access.log</span></span></code></pre></div><p>长此以往logs可能会高达几百G，从而导致服务器出现 <code>No space left on device</code> 空间不足。</p><p>使用 df 可以查看磁盘信息，来确认问题原因。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">df</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span></span></code></pre></div><p>查看磁盘空间：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Filesystem      Size  Used Avail Use%</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/dev/sda1        80G   65G   15G   82%</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/dev/sda2       200G  150G   50G   75%</span></span></code></pre></div><ul><li>size: 总大小</li><li>used: 已经使用的大小</li><li>avail: 可用大小</li><li>use%: 使用率</li></ul><p>Use% 超过 80% 就需要考虑清理磁盘了。</p><h3 id="为什么加-h" tabindex="-1">为什么加 -h？ <a class="header-anchor" href="#为什么加-h" aria-label="Permalink to &quot;为什么加 -h？&quot;">​</a></h3><p>不加 -h 输出的计量单位是 Byte，查看不便。</p><p>使用 -h 后，输出的单位是 GB、MB、KB 等高可读的单位。</p><h2 id="du-查看目录大小" tabindex="-1">du（查看目录大小） <a class="header-anchor" href="#du-查看目录大小" aria-label="Permalink to &quot;du（查看目录大小）&quot;">​</a></h2><p><code>df</code> 告诉你磁盘满了，但是不知道哪个目录占用了这么多空间。</p><p>而 <code>du</code> 解决了这个问题。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">du</span></span></code></pre></div><h3 id="查看当前目录大小" tabindex="-1">查看当前目录大小 <a class="header-anchor" href="#查看当前目录大小" aria-label="Permalink to &quot;查看当前目录大小&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">du</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>输出示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>13G .</span></span></code></pre></div><h3 id="查看-logs" tabindex="-1">查看 logs <a class="header-anchor" href="#查看-logs" aria-label="Permalink to &quot;查看 logs&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">du</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span></span></code></pre></div><p>输出示例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>8.2G logs</span></span></code></pre></div><h3 id="查看所有目录" tabindex="-1">查看所有目录 <a class="header-anchor" href="#查看所有目录" aria-label="Permalink to &quot;查看所有目录&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">du</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-depth=1</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2G logs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>500M upload</span></span>
<span class="line"><span></span></span>
<span class="line"><span>30M config</span></span>
<span class="line"><span></span></span>
<span class="line"><span>100K tmp</span></span></code></pre></div><h2 id="free-查看内存" tabindex="-1">free（查看内存） <a class="header-anchor" href="#free-查看内存" aria-label="Permalink to &quot;free（查看内存）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">free</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span></span></code></pre></div><p>查看服务器还有多少内存。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>               total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:           3.6Gi       1.7Gi       599Mi       1.8Mi       1.6Gi       1.9Gi</span></span></code></pre></div><p>Mem（物理内存）:</p><blockquote><p>表示真实的内存条</p></blockquote><ul><li>total: 总内存</li><li>used: 已使用</li><li>free: 完全空闲（真正什么都没放的内存）</li><li>shared: 共享内存（多个程序共享同一块内存）</li><li>buff/cache: 缓存和缓冲区（空着的内存拿来作为缓存）</li><li>available: 可用内存（包括完全空闲的和本该空着但是拿去做缓存的）</li></ul><h2 id="chmod-权限" tabindex="-1">chmod（权限） <a class="header-anchor" href="#chmod-权限" aria-label="Permalink to &quot;chmod（权限）&quot;">​</a></h2><blockquote><p>chmod 权限 文件名</p></blockquote><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start.sh</span></span></code></pre></div><p>将 start.sh 的权限设置为 777，即所有人都有读写执行权限。</p><ul><li>read: 4（读）</li><li>write: 2（写）</li><li>execute: 1（执行）</li></ul><h3 id="加执行权限" tabindex="-1">加执行权限 <a class="header-anchor" href="#加执行权限" aria-label="Permalink to &quot;加执行权限&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chomd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start.sh</span></span></code></pre></div><h2 id="tar-压缩、解压" tabindex="-1">tar（压缩、解压） <a class="header-anchor" href="#tar-压缩、解压" aria-label="Permalink to &quot;tar（压缩、解压）&quot;">​</a></h2><p><strong>压缩</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -czvf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs.tar.gz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span></span></code></pre></div><p>含义：将 <code>logs</code> 压缩成 <code>logs.tar.gz</code></p><p><strong>解释</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -zxvf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs.tar.gz</span></span></code></pre></div><p>得到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>logs/</span></span></code></pre></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><ul><li>c: create 创建压缩包</li><li>z: gzip 压缩</li><li>v: 显示过程</li><li>f: 指定文件名</li></ul>`,54)]))}const g=a(t,[["render",n]]);export{k as __pageData,g as default};
